-- Location reference data: countries (ISO 3166-1) and the Viet Nam administrative hierarchy
-- (province/city -> district -> ward, 63 provinces as published by the General Statistics Office before the 2025 merger),
-- plus state/province -> city for Singapore, Thailand, Malaysia, Indonesia, Japan, South Korea, Cambodia and Laos
-- (stored in Cities / Districts; these countries have no ward level).
-- Generated from github.com/datasets/country-list, provinces.open-api.vn and github.com/dr5hn/countries-states-cities-database. Ids are deterministic UUIDv5 values,
-- so the script is idempotent and produces the same ids in every environment. Run with client_encoding = UTF8.
-- Proposed endpoints: docs/location-select-redesign.md section 16.

BEGIN;

CREATE TABLE IF NOT EXISTS "Countries" (
    "Id"        uuid         NOT NULL PRIMARY KEY,
    "Code"      varchar(2)   NOT NULL UNIQUE,
    "Name"      varchar(150) NOT NULL,
    "DeletedAt" timestamptz  NULL
);

CREATE TABLE IF NOT EXISTS "Cities" (
    "Id"           uuid         NOT NULL PRIMARY KEY,
    "CountryId"    uuid         NOT NULL REFERENCES "Countries" ("Id"),
    "Code"         varchar(20)  NOT NULL,
    "Name"         varchar(150) NOT NULL,
    "DivisionType" varchar(50)  NULL,
    "DeletedAt"    timestamptz  NULL,
    UNIQUE ("CountryId", "Code")
);

CREATE TABLE IF NOT EXISTS "Districts" (
    "Id"           uuid         NOT NULL PRIMARY KEY,
    "CityId"       uuid         NOT NULL REFERENCES "Cities" ("Id"),
    "Code"         varchar(20)  NOT NULL,
    "Name"         varchar(150) NOT NULL,
    "DivisionType" varchar(50)  NULL,
    "DeletedAt"    timestamptz  NULL,
    UNIQUE ("CityId", "Code")
);

CREATE TABLE IF NOT EXISTS "Wards" (
    "Id"           uuid         NOT NULL PRIMARY KEY,
    "DistrictId"   uuid         NOT NULL REFERENCES "Districts" ("Id"),
    "Code"         varchar(20)  NOT NULL,
    "Name"         varchar(150) NOT NULL,
    "DivisionType" varchar(50)  NULL,
    "DeletedAt"    timestamptz  NULL,
    UNIQUE ("DistrictId", "Code")
);

CREATE INDEX IF NOT EXISTS "IX_Cities_CountryId"    ON "Cities" ("CountryId");
CREATE INDEX IF NOT EXISTS "IX_Districts_CityId"    ON "Districts" ("CityId");
CREATE INDEX IF NOT EXISTS "IX_Wards_DistrictId"    ON "Wards" ("DistrictId");


-- Countries: 249 rows
ON CONFLICT ("Id") DO NOTHING;

-- Cities: 314 rows
ON CONFLICT ("Id") DO NOTHING;

-- Districts: 4509 rows
ON CONFLICT ("Id") DO NOTHING;
ON CONFLICT ("Id") DO NOTHING;
